    private fun wildcards(m: MutableMap<Int, Command>) {
        m[0x1320] = Command("bgm_fade_in", "EvtBgmFadeIn", listOf("bgm"), listOf(), listOf(u16("bgm", 1, valueKind = K_SONG)), "speed")
        m[0x1E20] = Command("display_face", "EvtDisplayFace", listOf("fid"), listOf(), listOf(u16("fid", 1)), "slot")
        m[0x2920] = Command("change_fog_vision", "EvtChangeFogVision", listOf("vision"), listOf(), listOf(u16("vision", 1)), "doDisplay")
        m[0x3240] = Command("load_single_unit", "EvtLoadSingleUnit", listOf("pid", "x", "y"), listOf(), listOf(u16("pid", 1, valueKind = K_CHARACTER), u8("x", 2), u8("y", 2, 8), u16(null, 3)), "faction")
    }

    /** Header word → command. */
    public val byHeader: Map<Int, Command> = HashMap<Int, Command>().also { m ->
        exact0(m)
        exact1(m)
        exact2(m)
        exact3(m)
        exact4(m)
    }

    /** Commands whose sub-command nibble is a parameter: `(cmd shl 8) or (len shl 4)` → command. */
    public val bySubParam: Map<Int, Command> = HashMap<Int, Command>().also { wildcards(it) }

    /**
     * The command for [header]: an exact [byHeader] row, else the [bySubParam] row of its cmd and
     * len.
     */
    public fun find(header: Int): Command? = byHeader[header] ?: bySubParam[header and 0xFFF0]
}
